package com.daniil.wristlens.core;
import org.junit.Test;import static org.junit.Assert.*;import java.io.*;import java.util.concurrent.atomic.AtomicInteger;
public class CopyTransferTest {
 @Test public void folderNormalizesAndRejectsTraversal(){assertEquals("DCIM/My photos/Trip",CopyProfile.folder(" DCIM\\My photos//Trip/ "));for(String path:new String[]{"DCIM/../Download","/DCIM/Camera","DCIM/./Camera","Pictures/Test","DCIM/","content://anything"})assertThrows(IllegalArgumentException.class,()->CopyProfile.folder(path));}
 @Test public void compressionPreservesAspectAndNeverUpscales(){CopyProfile p=CopyProfile.of("balanced");assertArrayEquals(new int[]{1920,1440},p.dimensions(4000,3000,false));assertArrayEquals(new int[]{720,1280},p.dimensions(1080,1920,true));assertArrayEquals(new int[]{640,480},p.dimensions(640,480,true));assertEquals("VID_20261025_000000_compact.mp4",CopyProfile.of("compact").copyName("VID_20261025_000000.webm",true));assertEquals("IMG.jpg",CopyProfile.of("original").copyName("IMG.jpg",false));assertThrows(IllegalArgumentException.class,()->CopyProfile.of("unbounded"));}
 @Test public void preparationHeartbeatsThenVerifiedFileRoundTrip()throws Exception{byte[] data={3,1,4,1,5};ByteArrayOutputStream wire=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(wire);CopyHandshake.waiting(out);CopyHandshake.waiting(out);CopyHandshake.ready(out,new CopyHandshake.Metadata("abc","copy.jpg","image/jpeg",data.length));OriginalTransfer.send(new ByteArrayInputStream(data),out,data.length,n->{});DataInputStream in=new DataInputStream(new ByteArrayInputStream(wire.toByteArray()));AtomicInteger pulses=new AtomicInteger();var m=CopyHandshake.receive(in,"abc",pulses::incrementAndGet);assertEquals(3,pulses.get());assertEquals(data.length,m.bytes());ByteArrayOutputStream saved=new ByteArrayOutputStream();OriginalTransfer.receive(in,saved,100,n->{});assertArrayEquals(data,saved.toByteArray());}
 @Test public void failedPreparationAndWrongIdentityCannotPublish()throws Exception{ByteArrayOutputStream wire=new ByteArrayOutputStream();CopyHandshake.error(new DataOutputStream(wire),"Encoder unavailable");IOException error=assertThrows(IOException.class,()->CopyHandshake.receive(new DataInputStream(new ByteArrayInputStream(wire.toByteArray())),"id",()->{}));assertEquals("Encoder unavailable",error.getMessage());wire.reset();CopyHandshake.ready(new DataOutputStream(wire),new CopyHandshake.Metadata("wrong","x.mp4","video/mp4",123));assertThrows(IOException.class,()->CopyHandshake.receive(new DataInputStream(new ByteArrayInputStream(wire.toByteArray())),"id",()->{}));}
}
